func TestReadinessUpdatesAggregateMetrics(t *testing.T){s:=testServer(t);r:=httptest.NewRequest("GET","/readyz",nil);w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusServiceUnavailable{t.Fatalf("readyz status=%d",w.Code)};r=httptest.NewRequest("GET","/metrics",nil);w=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);body:=w.Body.String();for _,want:=range []string{"botweb_bots_checked 1","botweb_bots_reachable 0"}{if !strings.Contains(body,want){t.Fatalf("missing %q in metrics: %s",want,body)}}}


func TestLoginRequiresFormContentType(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};r:=httptest.NewRequest("POST","http://botweb.local/login",strings.NewReader("token=view"));r.Host="botweb.local";r.Header.Set("Content-Type","text/plain");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusUnsupportedMediaType{t.Fatalf("status=%d, want 415",w.Code)}}


func TestLoginIgnoresQueryCredentialField(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"body-value"};r:=httptest.NewRequest("POST","http://botweb.local/login?token=query-sentinel",strings.NewReader("token=body-value"));r.Host="botweb.local";r.Header.Set("Content-Type","application/x-www-form-urlencoded");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusSeeOther{t.Fatalf("status=%d, want 303",w.Code)}}


func TestSessionEndpointsAreNoStore(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view",OperatorToken:"op"};cases:=[]struct{method,path,body,token string}{{"GET","/login","",""},{"POST","/login","token=view",""},{"GET","/api/v1/session","","view"}};for _,tc:=range cases{r:=httptest.NewRequest(tc.method,"http://botweb.local"+tc.path,strings.NewReader(tc.body));r.Host="botweb.local";if tc.body!=""{r.Header.Set("Content-Type","application/x-www-form-urlencoded")};if tc.token!=""{r.Header.Set("Authorization","Bearer "+tc.token)};w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if got:=w.Header().Get("Cache-Control");got!="no-store"{t.Fatalf("%s %s Cache-Control=%q",tc.method,tc.path,got)}}}


func TestLoginSessionCookieSecurityAttributes(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view",TrustProxy:true};r:=httptest.NewRequest("POST","http://botweb.local/login",strings.NewReader("token=view"));r.Host="botweb.local";r.Header.Set("Content-Type","application/x-www-form-urlencoded");r.Header.Set("Origin","https://botweb.local");r.Header.Set("X-Forwarded-Proto","https");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusSeeOther{t.Fatalf("status=%d",w.Code)};cs:=w.Result().Cookies();if len(cs)!=1{t.Fatalf("cookies=%d",len(cs))};c:=cs[0];if c.Name!="botweb_session"||!c.HttpOnly||!c.Secure||c.SameSite!=http.SameSiteStrictMode||c.Path!="/"{t.Fatalf("unexpected session cookie: %#v",c)}}

func TestLogoutExpiresSessionCookie(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};r:=httptest.NewRequest("POST","http://botweb.local/logout",nil);r.Host="botweb.local";r.Header.Set("Authorization","Bearer view");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);cs:=w.Result().Cookies();if len(cs)!=1{t.Fatalf("cookies=%d",len(cs))};c:=cs[0];if c.Name!="botweb_session"||c.MaxAge>=0||!c.HttpOnly||c.SameSite!=http.SameSiteStrictMode||c.Path!="/"{t.Fatalf("unexpected logout cookie: %#v",c)}}


func loginRequest(s *Server,token string)*httptest.ResponseRecorder{r:=httptest.NewRequest("POST","http://botweb.local/login",strings.NewReader("token="+token));r.Host="botweb.local";r.Header.Set("Content-Type","application/x-www-form-urlencoded");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);return w}
func TestLoginRateLimitAfterTenFailures(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};for i:=0;i<10;i++{if w:=loginRequest(s,"bad");w.Code!=http.StatusUnauthorized{t.Fatalf("attempt %d status=%d",i+1,w.Code)}};if w:=loginRequest(s,"bad");w.Code!=http.StatusTooManyRequests{t.Fatalf("limited status=%d, want 429",w.Code)}}
func TestSuccessfulLoginClearsFailureLimiter(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};for i:=0;i<9;i++{if w:=loginRequest(s,"bad");w.Code!=http.StatusUnauthorized{t.Fatalf("attempt %d status=%d",i+1,w.Code)}};if w:=loginRequest(s,"view");w.Code!=http.StatusSeeOther{t.Fatalf("success status=%d",w.Code)};for i:=0;i<9;i++{if w:=loginRequest(s,"bad");w.Code!=http.StatusUnauthorized{t.Fatalf("post-reset attempt %d status=%d",i+1,w.Code)}}}

func TestValidLoginAllowedAfterFailureLimit(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};for i:=0;i<10;i++{if w:=loginRequest(s,"bad");w.Code!=http.StatusUnauthorized{t.Fatalf("attempt %d status=%d",i+1,w.Code)}};if w:=loginRequest(s,"bad");w.Code!=http.StatusTooManyRequests{t.Fatalf("limited bad login status=%d",w.Code)};if w:=loginRequest(s,"view");w.Code!=http.StatusSeeOther{t.Fatalf("valid login blocked by failure limiter: %d",w.Code)}}

func TestLoginRateLimitIncludesRetryAfter(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};for i:=0;i<10;i++{loginRequest(s,"bad")};w:=loginRequest(s,"bad");if w.Code!=http.StatusTooManyRequests{t.Fatalf("status=%d",w.Code)};if got:=w.Header().Get("Retry-After");got!="60"{t.Fatalf("Retry-After=%q, want 60",got)}}

func TestLoginThrottleMetric(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};for i:=0;i<10;i++{loginRequest(s,"bad")};if w:=loginRequest(s,"bad");w.Code!=http.StatusTooManyRequests{t.Fatalf("throttle status=%d",w.Code)};r:=httptest.NewRequest("GET","/metrics",nil);r.Header.Set("Authorization","Bearer view");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusOK{t.Fatalf("metrics status=%d",w.Code)};if !strings.Contains(w.Body.String(),"botweb_login_throttled_total 1\n"){t.Fatalf("missing throttle metric: %s",w.Body.String())}}

func TestLoginRejectsOversizedBody(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};body:="token="+strings.Repeat("x",5000);r:=httptest.NewRequest("POST","http://botweb.local/login",strings.NewReader(body));r.Host="botweb.local";r.Header.Set("Content-Type","application/x-www-form-urlencoded");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusRequestEntityTooLarge{t.Fatalf("status=%d, want 413",w.Code)}}

func TestAPIResponsesAreNoStore(t *testing.T){s:=testServer(t);s.auth=AuthConfig{ViewerToken:"view"};r:=httptest.NewRequest("GET","/api/v1/bots",nil);r.Header.Set("Authorization","Bearer view");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusOK{t.Fatalf("status=%d",w.Code)};if got:=w.Header().Get("Cache-Control");got!="no-store"{t.Fatalf("Cache-Control=%q, want no-store",got)}}

func TestMediaTypeParsing(t *testing.T){for _,tc:=range []struct{ct,want string;ok bool}{{"application/json","application/json",true},{"application/json; charset=utf-8","application/json",true},{"application/jsonx","application/json",false},{"application/json; charset=","application/json",false},{"application/x-www-form-urlencoded; charset=UTF-8","application/x-www-form-urlencoded",true}}{r:=httptest.NewRequest("POST","/",nil);r.Header.Set("Content-Type",tc.ct);if got:=hasMediaType(r,tc.want);got!=tc.ok{t.Fatalf("Content-Type %q got %v want %v",tc.ct,got,tc.ok)}}}

func TestDecodeJSONBodyRejectsTrailingValue(t *testing.T){var v map[string]any;r:=httptest.NewRequest("POST","/",strings.NewReader("{\"id\":\"x\"}{\"id\":\"y\"}"));w:=httptest.NewRecorder();if e:=decodeJSONBody(w,r,&v);e==nil{t.Fatal("expected trailing JSON value to be rejected")}}
func TestDecodeJSONBodyAcceptsSingleValue(t *testing.T){var v map[string]any;r:=httptest.NewRequest("POST","/",strings.NewReader("{\"id\":\"x\"}\n"));w:=httptest.NewRecorder();if e:=decodeJSONBody(w,r,&v);e!=nil{t.Fatalf("single JSON value rejected: %v",e)};if v["id"]!="x"{t.Fatalf("id=%v",v["id"])}}

type strictJSONTestRequest struct{ID string `json:"id"`}
func TestDecodeJSONBodyRejectsUnknownField(t *testing.T){var v strictJSONTestRequest;r:=httptest.NewRequest("POST","/",strings.NewReader("{\"id\":\"x\",\"typo\":true}"));w:=httptest.NewRecorder();if e:=decodeJSONBody(w,r,&v);e==nil{t.Fatal("expected unknown JSON field to be rejected")}}

func TestJSONDecodeErrorReportsOversize(t *testing.T){var v strictJSONTestRequest;r:=httptest.NewRequest("POST","/",strings.NewReader("{\"id\":\""+strings.Repeat("x",5000)+"\"}"));w:=httptest.NewRecorder();e:=decodeJSONBody(w,r,&v);if e==nil{t.Fatal("expected oversized JSON error")};out:=httptest.NewRecorder();writeJSONDecodeError(out,e);if out.Code!=http.StatusRequestEntityTooLarge{t.Fatalf("status=%d, want 413",out.Code)}}

func TestDecodeJSONBodyRejectsEmptyBody(t *testing.T){var v strictJSONTestRequest;r:=httptest.NewRequest("POST","/",nil);w:=httptest.NewRecorder();e:=decodeJSONBody(w,r,&v);if e==nil{t.Fatal("expected empty JSON body to be rejected")};out:=httptest.NewRecorder();writeJSONDecodeError(out,e);if out.Code!=http.StatusBadRequest{t.Fatalf("status=%d, want 400",out.Code)}}

func TestChannelWriteRequiresNetworkAndName(t *testing.T){for _,body:=range []string{`{"network":"","name":"#test"}`,`{"network":"net","name":"   "}`}{s:=testServer(t);s.auth=AuthConfig{OperatorToken:"op"};r:=httptest.NewRequest("POST","/api/v1/bots/x/channels/join",strings.NewReader(body));r.Header.Set("Authorization","Bearer op");r.Header.Set("Content-Type","application/json");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusBadRequest{t.Fatalf("body=%s status=%d, want 400",body,w.Code)}}}

func TestModuleWriteRequiresID(t *testing.T){for _,body:=range []string{`{"id":""}`,`{"id":"   "}`}{s:=testServer(t);s.auth=AuthConfig{OperatorToken:"op"};r:=httptest.NewRequest("POST","/api/v1/bots/x/modules/reload",strings.NewReader(body));r.Header.Set("Authorization","Bearer op");r.Header.Set("Content-Type","application/json");w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusBadRequest{t.Fatalf("body=%s status=%d, want 400",body,w.Code)}}}

func TestMethodNotAllowedIncludesAllow(t *testing.T){s:=testServer(t);for _,tc:=range []struct{method,path,allow string}{{"POST","/healthz","GET, HEAD"},{"PUT","/api/v1/bots","GET, HEAD"},{"GET","/logout","POST"}}{r:=httptest.NewRequest(tc.method,tc.path,nil);w:=httptest.NewRecorder();s.Handler().ServeHTTP(w,r);if w.Code!=http.StatusMethodNotAllowed{t.Fatalf("%s %s status=%d, want 405",tc.method,tc.path,w.Code)};if got:=w.Header().Get("Allow");got!=tc.allow{t.Fatalf("%s %s Allow=%q, want %q",tc.method,tc.path,got,tc.allow)}}}
